%% ===========================================================================
%% ANEXO A - CENSO DE PINES. RE-MEDIDO SOBRE EL FUENTE EL 05/09/2026
%%
%% 🔴 LOS DOS pines.h YA NO SON BYTE-IDENTICOS, y la frase de abajo llevaba
%%    dias siendo falsa. Aqui ponia:
%%      "son BYTE-IDENTICOS: md5 = d5d0be19911e0ec9b19ed6e55f799d08"
%%    MEDIDO HOY, y ninguno de los dos es ya ese md5:
%%      32b6e2b6029102d6e95bee135097b9e3   Maestro/include/pines.h   167 lineas
%%      fc6a477eb556af48754bba56baf43cb4   Esclavo/include/pines.h   166 lineas
%%
%%    LO QUE DIFIERE ES SOLO COMENTARIO, y hay que decirlo con precision
%%    porque la conclusion util cambia segun cual sea: el BLOQUE DE #define
%%    -los diecinueve pines- SIGUE SIENDO IDENTICO. Lo que diverge es la
%%    cabecera de N-118: el arreglo de 273b315 corrigio la frase falsa
%%    "INPUT_PULLUP, activo en BAJO" en el Maestro y NO TOCO EL ESCLAVO, asi
%%    que durante unas horas el Poste 2 -el que esta a 1000 m- llevo la
%%    cabecera equivocada. Hoy las dos estan bien y cuentan la historia
%%    distinto, por eso el md5 no vuelve a casar.
%%
%%    LA REGLA QUE DEJA: un md5 en un documento es un HASH DE TODO, comentarios
%%    incluidos, asi que caduca cada vez que alguien toca una coma y deja de
%%    decir lo que se queria decir. Si lo que importa es que los PINES sean los
%%    mismos, se compara el bloque de #define, no el fichero:
%%      diff <(grep '^#define' Maestro/include/pines.h) \
%%           <(grep '^#define' Esclavo/include/pines.h)   -> vacio [MEDIDO 05/09]
%%
%% El censo es grep de pinMode / digitalRead / digitalWrite sobre src/, no
%% lectura -CLAUDE.md seccion 3.ter-.
%%
%% pin   nombre            bornera  estado                          evidencia
%% ----  ----------------  -------  ------------------------------  --------------------------
%% [RE-MEDIDO 05/09: las seis lineas de escritura se movieron de :49-:54 a
%%  :61-:66. Se dan por su SIMBOLO, que es lo que no caduca: las seis viven
%%  dentro de escribirPines(), grep -n "static void escribirPines" -> :60]
%% PA0   ROJO1             J3       VIVO   OUTPUT                   semaforo.cpp:61 en escribirPines()
%% PA1   AMARILLO1         J4       VIVO   OUTPUT                   semaforo.cpp:63 en escribirPines()
%% PA2   VERDE1            J5       VIVO   OUTPUT                   semaforo.cpp:65 en escribirPines()
%% PA3   ROJO2             J6       VIVO   OUTPUT                   semaforo.cpp:62 en escribirPines()
%% PA4   AMARILLO2         J7       VIVO   OUTPUT                   semaforo.cpp:64 en escribirPines()
%% PA5   VERDE2            J8       VIVO   OUTPUT                   semaforo.cpp:66 en escribirPines()
%%                                            [Y OJO CON ESTE, que no es firmware:
%%                                             el LED D21 del canal VERDE2 -Q6 -> J8- tiene
%%                                             el CATODO SIN CONECTAR, red unconnected-
%%                                             (D21-K-Pad1), cero pistas y cero hilos. Es el
%%                                             UNICO de los diez sin indicador, y J8 p2 FLOTA
%%                                             en reposo en vez de subir a ~12 V como los otros
%%                                             nueve. SIN VERIFICAR si es defecto o decision:
%%                                             es A-10 de DECISIONES.md, y es de BANCO]
%% PA6   ROJO_PEATON       J11      MUERTO declarado, sin uso       pines.h + coment. M:main.cpp:35
%% PA7   VERDE_PEATON      J9       MUERTO declarado, sin uso       pines.h + coment. M:main.cpp:35
%%                                            [PRECISADO 02/09: el comentario esta SOLO en el
%%                                             Maestro. En el Esclavo estos dos nombres no
%%                                             aparecen fuera de pines.h ni una vez]
%% PA8   RS485_IN_DE_RE    U2       VIVO   OUTPUT HIGH              M: bluetooth.cpp:135-136
%%                                                                  E: bluetooth.cpp:163-164
%%                                            [CORREGIDO 02/09: decia :68-69 / :76-77, que hoy
%%                                             son un comentario del registro de J17. No es que
%%                                             el pin cambiara: se movio el codigo]
%%                                            [RE-MEDIDO 05/09: se habian movido OTRA VEZ, una
%%                                             linea y dos. Van por simbolo:
%%                                             grep -n RS485_IN_DE_RE Maestro/src/bluetooth.cpp
%%                                             Es la tercera vez que esta fila caduca en cuatro
%%                                             dias, y es el argumento entero de CLAUDE.md
%%                                             4.sexies: se cita el simbolo, no la linea]
%% PA9   RS485_IN_TX       J10      MUERTO declarado, sin uso       solo pines.h
%% PA10  RS485_IN_RX       J10      MUERTO declarado, sin uso       solo pines.h
%% PB0   CAM_DEMANDA_PIN   J14      VIVO   INPUT, activo en ALTO    M: botones.cpp:410 -decia :155-
%%                                                                  E: main.cpp:288 / :350
%% PB1   BUZZER            J13      MUERTO declarado, sin uso       solo pines.h
%% PB2   MOTOR_TALANQUERA  J15      VIVO   OUTPUT, reposo CERRAR    semaforo.cpp:120, :231 -decia :93, :203-204-
%% PB3   LCD_SCLK          J17 p4   DECLARADO, YA NO SE CONDUCE     lcd.cpp: U8X8_PIN_NONE
%% PB4   LCD_CS            J17 p1   DECLARADO, YA NO SE CONDUCE     lcd.cpp: U8X8_PIN_NONE
%% PB5   LCD_SID           J17 p5   DECLARADO, YA NO SE CONDUCE     lcd.cpp: U8X8_PIN_NONE
%% PB6   "LCD_PSB" -> TX   J17 p3   VIVO   USART1 remapeado, TX BT  bluetooth.cpp:30 M / :29 E -NO es la misma-
%% PB7   "LCD_RST" -> RX   J17 p2   VIVO   USART1 remapeado, RX BT  bluetooth.cpp:30 M / :29 E -decia ":28 en LAS DOS"-
%%                                            [CORREGIDO 02/09: decia ":28 / :26". La declaracion
%%                                             del Esclavo esta hoy tambien en :28 y es BYTE-
%%                                             IDENTICA a la del Maestro. Dos puntas que en esto
%%                                             SI son simetricas, al contrario que PA8]
%% PB8   LED_TESTIGO       -        pinMode(INPUT) SIN LECTURA      DELIBERADO, pines.h:48-63
%% PB9   BOTON1 / mando A  J16 p5   VIVO   INPUT pelado, act. ALTO  pines.h:146, botones.cpp:394
%% PB10  RS485_OUT_TX      J12      VIVO   USART3 - radio LoRa      pines.h
%% PB11  RS485_OUT_RX      J12      VIVO   USART3 - radio LoRa      pines.h
%% PB12  LORA_DE_RE        J12      VIVO   OUTPUT                   pines.h
%% PB13  BOTON2 / mando B  J16 p8   VIVO   INPUT pelado, act. ALTO  pines.h:147, botones.cpp:395
%% PB14  CAM_C_PIN         J16 p10  VIVO   INPUT pelado, act. ALTO  pines.h:148, botones.cpp:411
%% PB15  CAM_D_PIN         J16 p12  VIVO   INPUT pelado, act. ALTO  pines.h:149, botones.cpp:412
%%
%% 🔴 LAS DOS FILAS DE PB9 Y PB13 DECIAN "INPUT_PULLUP, act. BAJO" Y ERA FALSO.
%%    Corregido el 05/09. Describian el firmware ANTERIOR a 346ea5f -"fix(N-118):
%%    el mando A/B pasa a activo en ALTO - lo decide el cobre"-. Medido hoy, y el
%%    grep se publica porque un grep sin correr es la misma cita rota una capa
%%    arriba:
%%
%%      $ grep -n "pinMode(BOTON1\|lecturaCruda" Maestro/src/botones.cpp
%%      42:  bool lecturaCruda = (digitalRead(b.pin) == HIGH);
%%      394:  pinMode(BOTON1, INPUT);
%%
%%    En el Esclavo lo mismo en :412 y :56. LAS CUATRO POSICIONES DE J16 LLEVAN
%%    HOY LA MISMA POLARIDAD, sin excepcion.
%%
%%    POR QUE IMPORTA Y NO ES UNA ERRATA: quien cablee leyendo la fila vieja
%%    cierra el pulsador CONTRA MASA. Con INPUT pelado y pull-down, un contacto
%%    contra masa NO ARMA NUNCA la senal -queda 0 V pulsado y 0 V en reposo-, asi
%%    que MANDO_B no arma jamas ambarLocal y EL VETO DE SFTY-21 QUEDA ABIERTO:
%%    una orden de radio sacaria del ambar a una punta cuyo operario lo pidio, y
%%    ningun test lo diria.
%%
%%    Y ADEMAS EL GESTO ES IMPOSIBLE EN ESTE CONECTOR: J16 tiene UNA SOLA MASA en
%%    todo el conector -p2-, y un pin de 3,3 V pegado a cada posicion de senal
%%    -p4/p5, p7/p8, p9/p10, p11/p12-. Un contacto por posicion contra masa
%%    necesitaria una masa por posicion. La frase "van contra masa" es la que
%%    CLAUDE.md 2.ter cita como ejemplo de excepcion escrita y nunca comprobada.
%%
%% Sin cablear en la tarjeta: PA11, PA12, PA15, PC13.  [ESCRITO en pines.h:60-61]
%% -no comprobado contra el netlist en esta pasada-.
%%
%% 🔴 ESTE PARRAFO DECIA QUE J16 TENIA DOS POLARIDADES. ES FALSO Y SE TACHA.
%%    Ponia: "LAS DOS POLARIDADES DE J16 CONVIVEN A PROPOSITO... INPUT_PULLUP +
%%    activo en BAJO para los botones A y B (pulsador contra masa), INPUT pelado
%%    + activo en ALTO para las tres camaras". No se borra porque una correccion
%%    que desaparece en silencio se vuelve a proponer.
%%
%% LO QUE HAY DE VERDAD, y botones.cpp sigue siendo el dueno unico de J16:
%% UNA SOLA POLARIDAD PARA LAS CUATRO POSICIONES - INPUT pelado + activo en ALTO,
%% contacto seco que CIERRA CONTRA LOS 3,3 V, con R65-R68 de 10K a masa fijando
%% el reposo. Es lo que pide el cobre y es lo que hace el fuente desde 346ea5f.
%%
%% Y ESTA MEDIDO CON PUNTAS, no deducido - paso 20 de la Guia de banco, 03/09,
%% con 617bd00 dentro de la tarjeta, que llevaba PULL-UP en A/B y pelado en C/D:
%%     R a masa   9,92 - 9,94 kOhm   en los CUATRO pines
%%     reposo     0,6 V en MANDO_A y MANDO_B  (los dos con INPUT_PULLUP)
%%                0 V   en CAM_C y CAM_D      (los dos con INPUT pelado)
%% Mismo cobre, distinto pinMode, distinta tension: el banco corrio las dos ramas
%% del experimento en la misma tabla sin que nadie lo leyera asi. Los 0,6 V que se
%% llevaban meses contando como "defecto de placa" son exactamente el divisor del
%% pull-up interno contra los 10K, o sea la prueba de que R65-R68 estan montadas.
%%
%% (La cuenta original de N-67 no era mala: era correcta PARA EL FIRMWARE DE
%%  ENTONCES. Lo que caduco no es la aritmetica, es el sujeto.)
%%
%% ===========================================================================
%% ANEXO B - LAS DOS PUNTAS NO SON SIMETRICAS, Y ESTA MEDIDO
%%
%% 1. N-97 CERRADO (deeeab4): la camara de demanda YA NO vive dentro de un modo.
%%    Antes el Maestro hacia el pinMode DENTRO de modoInteligente_setup(), asi
%%    que fuera de ese modo el pin NO EXISTIA. Hoy las dos puntas declaran sus
%%    entradas en el arranque y sin condicion, y el lector es codigo identico:
%%    camara_leerPin().
%%
%%    LO QUE SIGUE SIENDO ASIMETRICO, y hay que saberlo porque los instrumentos
%%    leen POR RUTA (CLAUDE.md seccion 5):
%%      - CAM_DEMANDA_PIN se declara en Maestro/src/botones.cpp:410 pero en
%%        Esclavo/src/main.cpp:288. Un pack que censara solo botones.cpp veria
%%        tres entradas en una punta y dos en la otra sin que haya defecto.
%%      - PB0 se lee por NIVEL en el Maestro y por FLANCO en el Esclavo. Esta
%%        razonado y va como reportar(), no como fallo: es SFTY-27 -"cede si el
%%        otro pide Y NO hay cola local", y "hay cola ahora" es un nivel, no un
%%        suceso-.
%%
%% 2. mando_ambarLocal() SOLO EXISTE COMO VETO EN EL ESCLAVO, y son CINCO
%%    llamadas vivas, no tres. RE-MEDIDO 05/09, grep publicado:
%%
%%      $ grep -rn "mando_ambarLocal" 01_Firmware/Esclavo/src/
%%      bluetooth.cpp:577:      if (semaforo_estado() == S_FALLO && !mando_ambarLocal()) {
%%      bluetooth.cpp:588:      if (mando_ambarLocal()) {
%%      main.cpp:453:      if (!mando_ambarLocal() && !bluetooth_ambarEmergencia()) {
%%      main.cpp:476:      if (!mando_ambarLocal() && !bluetooth_ambarEmergencia()) {
%%      main.cpp:617:    if (!mando_ambarLocal() && !bluetooth_ambarEmergencia() &&
%%      mando.cpp:103:bool mando_ambarLocal() { return ambarLocal; }
%%
%%    [CORREGIDO 05/09: decia "tres consumidores en main.cpp:406, :416 y :540".
%%     Las tres lineas se movieron Y ademas faltaban las dos de bluetooth.cpp,
%%     que deciden CANCELAR_AMBAR. Contar de menos en un censo de veto es peor
%%     que no censar: da una cifra con aspecto de completa]
%%
%%    Mientras un operario pidio ambar local, una orden de radio NO saca a esa
%%    punta del ambar. Es SFTY-21, y DECISIONES.md D-8 lo ratifico el 04/09:
%%    el ambar de emergencia CONSERVA SUS DOS VETOS -mando y app-, porque el
%%    banco tumbo DOS VECES la version sin cerrojo y al medirlo el veto NO era
%%    la causa del bloqueo.
%%
%%    🔴 Y EL MATIZ QUE CAMBIO EL 05/09: el mando FISICO se retiro (D-1), pero
%%    EL CODIGO NO SE TOCA. Retirar el armador de esa bandera no deja cinco if
%%    inertes: los deja SIEMPRE CIERTOS, o sea BORRA EL VETO. Con el mando
%%    desmontado la bandera simplemente no se arma nunca, que es lo correcto.
%%    Ademas el banco se caeria en ABORTADO y no en rojo: son TRECE packs, y
%%    los dos modelos leen constantes de mando.cpp EN EL IMPORT.
%%
%% 3. semaforo_iniciarFallo() esta en :272 en el Maestro y en :292 en el
%%    Esclavo [RE-MEDIDO 05/09: decia :242 y :256; grep -n "void
%%    semaforo_iniciarFallo" sobre las dos puntas]. Mismo codigo, distinto
%%    sitio: las rutas y las lineas que citan los instrumentos NO son
%%    intercambiables entre puntas. Y la propia fila lo demuestra dos veces:
%%    ha caducado en las dos puntas a la vez, conservando la diferencia.
%%
